// Hidden E2E grading suite for the uniseg (Unicode text segmentation) WRG task.
// GENERATED — do not hand-edit. Cases are the official Unicode 15.0.0 break-test
// vectors, grouped into UAX rule buckets (capped for comparable weight). External
// uniseg_test package: PUBLIC API only. One top-level func Test == one CTRF entry.
package uniseg_test

import (
	"testing"

	uniseg "github.com/rivo/uniseg"
)

type tc = struct {
	original string
	expected [][]rune
}

func segEqual(got, want [][]rune) bool {
	if len(got) != len(want) {
		return false
	}
	for i := range got {
		if len(got[i]) != len(want[i]) {
			return false
		}
		for j := range got[i] {
			if got[i][j] != want[i][j] {
				return false
			}
		}
	}
	return true
}

func runSeg(t *testing.T, cases []tc, seg func(string) [][]rune) {
	t.Helper()
	fails := 0
	for i, c := range cases {
		if !segEqual(seg(c.original), c.expected) {
			fails++
			if fails <= 8 {
				t.Errorf("case %d %q: got %v, want %v", i, c.original, seg(c.original), c.expected)
			}
		}
	}
	if fails > 8 {
		t.Errorf("... and %d more failing cases (of %d)", fails-8, len(cases))
	}
}

func segGraphemes(s string) [][]rune {
	out := [][]rune{}
	g := uniseg.NewGraphemes(s)
	for g.Next() {
		out = append(out, g.Runes())
	}
	return out
}

func segWords(s string) [][]rune {
	out := [][]rune{}
	state := -1
	for len(s) > 0 {
		var w string
		w, s, state = uniseg.FirstWordInString(s, state)
		out = append(out, []rune(w))
	}
	return out
}

func segSentences(s string) [][]rune {
	out := [][]rune{}
	state := -1
	for len(s) > 0 {
		var sn string
		sn, s, state = uniseg.FirstSentenceInString(s, state)
		out = append(out, []rune(sn))
	}
	return out
}

func segLines(s string) [][]rune {
	out := [][]rune{}
	state := -1
	for len(s) > 0 {
		var seg string
		seg, s, _, state = uniseg.FirstLineSegmentInString(s, state)
		out = append(out, []rune(seg))
	}
	return out
}

// --- previously-untested public API ---

type countCase = struct {
	original string
	expected int
}

func runCount(t *testing.T, cases []countCase) {
	t.Helper()
	fails := 0
	for i, c := range cases {
		if got := uniseg.GraphemeClusterCount(c.original); got != c.expected {
			fails++
			if fails <= 8 {
				t.Errorf("case %d %q: GraphemeClusterCount = %d, want %d", i, c.original, got, c.expected)
			}
		}
	}
	if fails > 8 {
		t.Errorf("... and %d more (of %d)", fails-8, len(cases))
	}
}

type strCase = struct {
	original string
	expected string
}

func runReverse(t *testing.T, cases []strCase) {
	t.Helper()
	fails := 0
	for i, c := range cases {
		if got := uniseg.ReverseString(c.original); got != c.expected {
			fails++
			if fails <= 8 {
				t.Errorf("case %d %q: ReverseString = %q, want %q", i, c.original, got, c.expected)
			}
		}
	}
	if fails > 8 {
		t.Errorf("... and %d more (of %d)", fails-8, len(cases))
	}
}


// TestGraphemeEmojiRI: 10 official cases (capped 300).
var casesGraphemeEmojiRI = []tc{
	{original: "\U0001F1E6\U0001F1E6", expected: [][]rune{{0x1F1E6, 0x1F1E6}}},
	{original: "\U0001F1E6\U0001F1E7\U0001F1E8\u0062", expected: [][]rune{{0x1F1E6, 0x1F1E7}, {0x1F1E8}, {0x0062}}},
	{original: "\u0061\U0001F1E6\U0001F1E7\U0001F1E8\u0062", expected: [][]rune{{0x0061}, {0x1F1E6, 0x1F1E7}, {0x1F1E8}, {0x0062}}},
	{original: "\u0061\U0001F1E6\U0001F1E7\u200D\U0001F1E8\u0062", expected: [][]rune{{0x0061}, {0x1F1E6, 0x1F1E7, 0x200D}, {0x1F1E8}, {0x0062}}},
	{original: "\u0061\U0001F1E6\u200D\U0001F1E7\U0001F1E8\u0062", expected: [][]rune{{0x0061}, {0x1F1E6, 0x200D}, {0x1F1E7, 0x1F1E8}, {0x0062}}},
	{original: "\u0061\U0001F1E6\U0001F1E7\U0001F1E8\U0001F1E9\u0062", expected: [][]rune{{0x0061}, {0x1F1E6, 0x1F1E7}, {0x1F1E8, 0x1F1E9}, {0x0062}}},
	{original: "\u0061\U0001F3FF\U0001F476\u200D\U0001F6D1", expected: [][]rune{{0x0061, 0x1F3FF}, {0x1F476, 0x200D, 0x1F6D1}}},
	{original: "\U0001F476\U0001F3FF\u0308\u200D\U0001F476\U0001F3FF", expected: [][]rune{{0x1F476, 0x1F3FF, 0x0308, 0x200D, 0x1F476, 0x1F3FF}}},
	{original: "\U0001F6D1\u200D\U0001F6D1", expected: [][]rune{{0x1F6D1, 0x200D, 0x1F6D1}}},
	{original: "\u2701\u200D\u2701", expected: [][]rune{{0x2701, 0x200D, 0x2701}}},
}
func TestGraphemeEmojiRI(t *testing.T) { runSeg(t, casesGraphemeEmojiRI, segGraphemes) }

// TestGraphemeHangul: 13 official cases (capped 300).
var casesGraphemeHangul = []tc{
	{original: "\u1100\u1100", expected: [][]rune{{0x1100, 0x1100}}},
	{original: "\u1100\u1160", expected: [][]rune{{0x1100, 0x1160}}},
	{original: "\u1100\uAC00", expected: [][]rune{{0x1100, 0xAC00}}},
	{original: "\u1100\uAC01", expected: [][]rune{{0x1100, 0xAC01}}},
	{original: "\u1160\u1160", expected: [][]rune{{0x1160, 0x1160}}},
	{original: "\u1160\u11A8", expected: [][]rune{{0x1160, 0x11A8}}},
	{original: "\u11A8\u11A8", expected: [][]rune{{0x11A8, 0x11A8}}},
	{original: "\uAC00\u1160", expected: [][]rune{{0xAC00, 0x1160}}},
	{original: "\uAC00\u11A8", expected: [][]rune{{0xAC00, 0x11A8}}},
	{original: "\uAC01\u11A8", expected: [][]rune{{0xAC01, 0x11A8}}},
	{original: "\u1100\u1100", expected: [][]rune{{0x1100, 0x1100}}},
	{original: "\uAC00\u11A8\u1100", expected: [][]rune{{0xAC00, 0x11A8}, {0x1100}}},
	{original: "\uAC01\u11A8\u1100", expected: [][]rune{{0xAC01, 0x11A8}, {0x1100}}},
}
func TestGraphemeHangul(t *testing.T) { runSeg(t, casesGraphemeHangul, segGraphemes) }

